/**
 * The Phase 1 PostgreSQL schema: the single source for the tables. Migrations in
 * `drizzle/` are generated from this file by `drizzle-kit generate`.
 *
 * Closed value sets (semester terms, content types, audit actions, entity
 * names, outbox kinds) are read from `@vektorprogrammet/domain`,
 * so the database constraints and the domain schemas cannot disagree.
 *
 * Conventions:
 * - TypeScript property names equal the domain field names; SQL names are snake_case.
 * - Integer keys of domain tables are `GENERATED BY DEFAULT AS IDENTITY`, so the
 *   importer can keep legacy ids (it advances the sequences afterwards).
 * - Every timestamp is `timestamptz` and is written from Effect's `Clock`.
 * - Constraint names are explicit; `classifySqlFailure` maps the unique ones.
 */
import {
  ADMIN_LIST_ID,
  AccountState,
  ActualState,
  AuditAction,
  AuditClient,
  COMPANY_EMAIL_PATTERN,
  CodePurpose,
  EntityName,
  FileExtension,
  JobRun,
  OutboxMessage,
  ReportStatus,
  StoredContentType,
  SystemJob,
  TeamFunction,
  Term,
  WorkspaceMode,
} from "@vektorprogrammet/domain";
import { sql } from "drizzle-orm";
import type { SQL } from "drizzle-orm";
import {
  boolean,
  check,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
  varchar,
} from "drizzle-orm/pg-core";
import { Array as Arr, pipe, Record as Rec } from "effect";

/** A SQL string literal for a code constant (never user input). */
const literal = (value: string): string => `'${value.replaceAll("'", "''")}'`;

/** `<column> IN ('a', 'b', …)` over a closed set from the domain. */
const oneOf = (column: SQL, values: readonly string[]): SQL =>
  sql`${column} in (${sql.raw(pipe(values, Arr.map(literal), Arr.join(", ")))})`;

const instant = (name: string) =>
  timestamp(name, { mode: "date", withTimezone: true });

export const semesterTerm = pgEnum("semester_term", Term.literals);

export const outboxStatus = pgEnum("outbox_status", [
  "pending",
  "delivered",
  "dead",
]);

export const teamFunction = pgEnum("team_function", TeamFunction.literals);

/**
 * Constraint names that `classifySqlFailure` maps to `AlreadyExists`: the unique constraints and the exclusion
 * constraint of the memberships.
 */
export const UniqueConstraint = {
  departmentCity: "department_city_unique",
  membershipOverlap: "membership_no_overlap",
  personCompanyEmail: "person_company_email_unique",
  personEmail: "person_email_unique",
  semesterTermYear: "semester_term_year_unique",
  teamGroupEmail: "team_group_email_unique",
  teamName: "team_department_name_unique",
} as const;

export type UniqueConstraint =
  (typeof UniqueConstraint)[keyof typeof UniqueConstraint];

const fileKeyPattern = `^[0-9a-f]{64}\\.(${Arr.join(FileExtension.literals, "|")})$`;

/** C11: registered public files. Only registered keys are served (RULE-290 replacement). */
export const publicFile = pgTable(
  "public_file",
  {
    contentType: text("content_type").notNull(),
    deletedAt: instant("deleted_at"),
    key: text("key").primaryKey(),
    legacyPath: text("legacy_path"),
    name: varchar("name", { length: 255 }).notNull(),
    sha256: text("sha256").notNull(),
    size: integer("size").notNull(),
    uploadedAt: instant("uploaded_at").notNull(),
    uploadedBy: integer("uploaded_by"),
  },
  (t) => [
    unique("public_file_legacy_path_unique").on(t.legacyPath),
    check(
      "public_file_key_format",
      sql`${t.key} ~ ${sql.raw(literal(fileKeyPattern))}`
    ),
    check("public_file_key_hash", sql`left(${t.key}, 64) = ${t.sha256}`),
    check(
      "public_file_content_type",
      oneOf(sql`${t.contentType}`, StoredContentType.literals)
    ),
    check("public_file_size", sql`${t.size} >= 0`),
    check("public_file_name", sql`length(${t.name}) > 0`),
  ]
);

/** C1 departments. Legacy ids are kept by the importer; the city is unique. */
export const department = pgTable(
  "department",
  {
    active: boolean("active").notNull().default(true),
    address: text("address"),
    city: text("city").notNull(),
    email: text("email").notNull(),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    latitude: doublePrecision("latitude"),
    logoKey: text("logo_key").references(() => publicFile.key),
    longitude: doublePrecision("longitude"),
    name: text("name").notNull(),
    shortName: text("short_name").notNull(),
    slackChannel: text("slack_channel"),
  },
  (t) => [
    unique(UniqueConstraint.departmentCity).on(t.city),
    check("department_name", sql`length(${t.name}) > 0`),
    check("department_short_name", sql`length(${t.shortName}) > 0`),
    check("department_city", sql`length(${t.city}) > 0`),
  ]
);

/** C2 semesters: (term, year) is unique (RULE-144, RULE-237); the year is an integer (RULE-050). */
export const semester = pgTable(
  "semester",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    term: semesterTerm("term").notNull(),
    year: integer("year").notNull(),
  },
  (t) => [
    unique(UniqueConstraint.semesterTermYear).on(t.term, t.year),
    check("semester_year", sql`${t.year} between 1900 and 9999`),
  ]
);

/** C1 fields of study: every row belongs to exactly one department. */
export const fieldOfStudy = pgTable(
  "field_of_study",
  {
    departmentId: integer("department_id")
      .notNull()
      .references(() => department.id),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    name: text("name").notNull(),
    shortName: text("short_name").notNull(),
  },
  (t) => [
    index("field_of_study_department_idx").on(t.departmentId),
    check("field_of_study_name", sql`length(${t.name}) > 0`),
    check("field_of_study_short_name", sql`length(${t.shortName}) > 0`),
  ]
);

/** Spec 0006: one human known to Vektorprogrammet. The department is the field of study's (RULE-164). */
export const person = pgTable(
  "person",
  {
    companyEmail: text("company_email"),
    email: text("email").notNull(),
    emailVerified: boolean("email_verified").notNull().default(false),
    fieldOfStudyId: integer("field_of_study_id")
      .notNull()
      .references(() => fieldOfStudy.id),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    name: text("name").notNull(),
  },
  (t) => [
    uniqueIndex(UniqueConstraint.personEmail)
      .on(t.email)
      .where(sql`${t.emailVerified}`),
    uniqueIndex(UniqueConstraint.personCompanyEmail)
      .on(t.companyEmail)
      .where(sql`${t.companyEmail} is not null`),
    index("person_field_of_study_idx").on(t.fieldOfStudyId),
    check("person_email_lowercase", sql`${t.email} = lower(${t.email})`),
    check(
      "person_company_email_lowercase",
      sql`${t.companyEmail} is null or ${t.companyEmail} = lower(${t.companyEmail})`
    ),
    check("person_name", sql`length(${t.name}) > 0`),
  ]
);

/** One first-membership welcome claim per person; written only under that person's aggregate lock. */
export const welcomeLedger = pgTable("welcome_ledger", {
  personId: integer("person_id")
    .primaryKey()
    .references(() => person.id),
  recordedAt: instant("recorded_at").notNull(),
});

/** The domain's account state is separate from Better Auth's credentials. */
export const account = pgTable(
  "account",
  {
    personId: integer("person_id")
      .primaryKey()
      .references(() => person.id),
    state: text("state").notNull(),
  },
  (t) => [
    check(
      "account_state",
      oneOf(sql`${t.state}`, Rec.keys(AccountState.cases))
    ),
  ]
);

/** One current, hashed code per purpose and person. Resending atomically replaces it. */
export const code = pgTable(
  "code",
  {
    expiresAt: instant("expires_at").notNull(),
    hash: text("hash").notNull(),
    purpose: text("purpose").notNull(),
    subject: integer("subject")
      .notNull()
      .references(() => person.id),
    usedAt: instant("used_at"),
  },
  (t) => [
    primaryKey({
      columns: [t.purpose, t.subject],
      name: "code_purpose_subject_pk",
    }),
    unique("code_hash_unique").on(t.hash),
    check("code_purpose", oneOf(sql`${t.purpose}`, CodePurpose.literals)),
    check("code_hash_format", sql`${t.hash} ~ '^[0-9a-f]{64}$'`),
  ]
);

/** The only link from Better Auth to the domain is a unique person id. */
export const authUser = pgTable(
  "auth_user",
  {
    createdAt: instant("created_at").notNull(),
    email: text("email").notNull(),
    emailVerified: boolean("email_verified").notNull().default(false),
    id: text("id").primaryKey(),
    image: text("image"),
    name: text("name").notNull(),
    personId: integer("person_id")
      .notNull()
      .references(() => person.id),
    updatedAt: instant("updated_at").notNull(),
  },
  (t) => [
    unique("auth_user_person_unique").on(t.personId),
    unique("auth_user_email_unique").on(t.email),
  ]
);

export const authSession = pgTable(
  "auth_session",
  {
    createdAt: instant("created_at").notNull(),
    expiresAt: instant("expires_at").notNull(),
    id: text("id").primaryKey(),
    ipAddress: text("ip_address"),
    token: text("token").notNull(),
    updatedAt: instant("updated_at").notNull(),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => authUser.id, { onDelete: "cascade" }),
  },
  (t) => [
    unique("auth_session_token_unique").on(t.token),
    index("auth_session_user_idx").on(t.userId),
    check(
      "auth_session_no_ip",
      sql`${t.ipAddress} is null or ${t.ipAddress} = ''`
    ),
  ]
);

export const authAccount = pgTable(
  "auth_account",
  {
    accessToken: text("access_token"),
    accessTokenExpiresAt: instant("access_token_expires_at"),
    accountId: text("account_id").notNull(),
    createdAt: instant("created_at").notNull(),
    credentialVersion: integer("credential_version").notNull().default(0),
    id: text("id").primaryKey(),
    idToken: text("id_token"),
    password: text("password"),
    providerId: text("provider_id").notNull(),
    refreshToken: text("refresh_token"),
    refreshTokenExpiresAt: instant("refresh_token_expires_at"),
    scope: text("scope"),
    updatedAt: instant("updated_at").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => authUser.id, { onDelete: "cascade" }),
  },
  (t) => [
    unique("auth_account_provider_account_unique").on(
      t.providerId,
      t.accountId
    ),
    index("auth_account_user_idx").on(t.userId),
  ]
);

export const authVerification = pgTable(
  "auth_verification",
  {
    createdAt: instant("created_at").notNull(),
    expiresAt: instant("expires_at").notNull(),
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    updatedAt: instant("updated_at").notNull(),
    value: text("value").notNull(),
  },
  (t) => [index("auth_verification_identifier_idx").on(t.identifier)]
);

/**
 * A fake mailbox: only the local and preview sender layers can write it. `delivery_key` is the outbox row's id, the
 * key that a provider with idempotency would deduplicate on: a message that is delivered twice is captured once.
 */
export const capturedMail = pgTable(
  "captured_mail",
  {
    deliveryKey: text("delivery_key"),
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    recipient: text("recipient").notNull(),
    sentAt: instant("sent_at").notNull(),
    subject: text("subject").notNull(),
    text: text("text").notNull(),
  },
  (t) => [unique("captured_mail_delivery_key_unique").on(t.deliveryKey)]
);

/** The fake Slack workspace, beside the fake mailbox: a Slack post of a non-production deployment is kept here. */
export const capturedSlack = pgTable(
  "captured_slack",
  {
    channel: text("channel").notNull(),
    deliveryKey: text("delivery_key"),
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    sentAt: instant("sent_at").notNull(),
    text: text("text").notNull(),
  },
  (t) => [unique("captured_slack_delivery_key_unique").on(t.deliveryKey)]
);

/** A team of one department (RULE-157: the name is unique there). Deactivated, never deleted (RULE-233). */
export const team = pgTable(
  "team",
  {
    active: boolean("active").notNull().default(true),
    defaultTerm: smallint("default_term").notNull(),
    departmentId: integer("department_id")
      .notNull()
      .references(() => department.id),
    function: teamFunction("function").notNull(),
    /** The Google Workspace group of the team (spec 0008). A team without one gets an issue in the report, never a guessed address. */
    groupEmail: text("group_email"),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    name: text("name").notNull(),
  },
  (t) => [
    unique(UniqueConstraint.teamName).on(t.departmentId, t.name),
    uniqueIndex(UniqueConstraint.teamGroupEmail)
      .on(t.groupEmail)
      .where(sql`${t.groupEmail} is not null`),
    check("team_default_term", sql`${t.defaultTerm} in (1, 2)`),
    check(
      "team_group_email",
      sql`${t.groupEmail} is null or ${t.groupEmail} ~ ${sql.raw(literal(COMPANY_EMAIL_PATTERN.source))}`
    ),
    check("team_name", sql`length(${t.name}) > 0`),
  ]
);

/** The value list of positions (`Leder`, `Medlem`, …); the first migration seeds the legacy fixtures. */
export const position = pgTable(
  "position",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    name: text("name").notNull(),
  },
  (t) => [
    unique("position_name_unique").on(t.name),
    check("position_name", sql`length(${t.name}) > 0`),
  ]
);

/** Semesters in calendar order, one integer each: Vår before Høst, so Vår 2026 is 4052 and Høst 2026 is 4053. */
const ordinalOf = (term: string, year: string): SQL =>
  sql.raw(`${year} * 2 + (case when ${term} = 'HOST' then 1 else 0 end)`);

/**
 * A person's place in a team for a term (ADR 0002). The state (Planned, Active, Ended) is never stored: it is
 * calculated from the term and the current semester. `start ≤ end` is a check; the exclusion constraint
 * `membership_no_overlap` (a custom migration, which Drizzle cannot model) keeps one person's terms in one team from
 * overlapping.
 */
export const membership = pgTable(
  "membership",
  {
    endOrdinal: integer("end_ordinal").generatedAlwaysAs(
      ordinalOf("end_term", "end_year")
    ),
    endTerm: semesterTerm("end_term").notNull(),
    endYear: integer("end_year").notNull(),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    leader: boolean("leader").notNull().default(false),
    personId: integer("person_id")
      .notNull()
      .references(() => person.id),
    positionId: integer("position_id")
      .notNull()
      .references(() => position.id),
    startOrdinal: integer("start_ordinal").generatedAlwaysAs(
      ordinalOf("start_term", "start_year")
    ),
    startTerm: semesterTerm("start_term").notNull(),
    startYear: integer("start_year").notNull(),
    teamId: integer("team_id")
      .notNull()
      .references(() => team.id),
  },
  (t) => [
    index("membership_team_idx").on(t.teamId),
    index("membership_person_idx").on(t.personId),
    check("membership_term_order", sql`${t.startOrdinal} <= ${t.endOrdinal}`),
    check("membership_start_year", sql`${t.startYear} between 1900 and 9999`),
    check("membership_end_year", sql`${t.endYear} between 1900 and 9999`),
  ]
);

/**
 * The admin list as one row (spec 0006b): the row that `deactivateAccount`, `reactivateAccount`, `createAdminGrant` and
 * `deleteAdminGrant` lock first, because whether an Active administrator is left spans every administrator. It holds
 * no data; a migration inserts it (`admin_list_seeded`), and `ADMIN_LIST_ID` names it.
 */
export const adminList = pgTable(
  "admin_list",
  { id: integer("id").primaryKey() },
  (t) => [
    check(
      "admin_list_singleton",
      sql`${t.id} = ${sql.raw(String(ADMIN_LIST_ID))}`
    ),
  ]
);

/** `docs/system/administration.md`: a place on the admin list. The first one has no granter (given outside the system). */
export const adminGrant = pgTable(
  "admin_grant",
  {
    grantedBy: integer("granted_by").references(() => person.id),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    personId: integer("person_id")
      .notNull()
      .references(() => person.id),
    until: instant("until").notNull(),
  },
  (t) => [
    index("admin_grant_person_idx").on(t.personId),
    index("admin_grant_until_idx").on(t.until),
    check(
      "admin_grant_not_self",
      sql`${t.grantedBy} is null or ${t.grantedBy} <> ${t.personId}`
    ),
  ]
);

/** Which leader got the "ending soon" digest of which semester (spec 0006, falsifier 7): it goes out once. */
export const endingSoonDigest = pgTable(
  "ending_soon_digest",
  {
    personId: integer("person_id")
      .notNull()
      .references(() => person.id),
    recordedAt: instant("recorded_at").notNull(),
    term: semesterTerm("term").notNull(),
    year: integer("year").notNull(),
  },
  (t) => [
    primaryKey({
      columns: [t.personId, t.term, t.year],
      name: "ending_soon_digest_pk",
    }),
  ]
);

/** C2 admission periods. Phase 1 imports them; Phase 3 adds the repository and the editor. */
export const admissionPeriod = pgTable(
  "admission_period",
  {
    departmentId: integer("department_id")
      .notNull()
      .references(() => department.id),
    endsAt: instant("ends_at").notNull(),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    semesterId: integer("semester_id")
      .notNull()
      .references(() => semester.id),
    startsAt: instant("starts_at").notNull(),
  },
  (t) => [
    index("admission_period_department_idx").on(t.departmentId, t.semesterId),
    check("admission_period_window", sql`${t.endsAt} > ${t.startsAt}`),
  ]
);

/** C8 social events (RULE-188): the end is after the start. */
export const socialEvent = pgTable(
  "social_event",
  {
    departmentId: integer("department_id")
      .notNull()
      .references(() => department.id),
    description: text("description").notNull().default(""),
    endsAt: instant("ends_at").notNull(),
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    link: varchar("link", { length: 250 }),
    semesterId: integer("semester_id")
      .notNull()
      .references(() => semester.id),
    startsAt: instant("starts_at").notNull(),
    title: text("title").notNull(),
  },
  (t) => [
    index("social_event_department_semester_idx").on(
      t.departmentId,
      t.semesterId
    ),
    check("social_event_window", sql`${t.endsAt} > ${t.startsAt}`),
    check("social_event_title", sql`length(${t.title}) > 0`),
    check("social_event_description", sql`length(${t.description}) <= 5000`),
  ]
);

/**
 * Transactional outbox (architecture §4). Rows are written in the command's
 * transaction and delivered after commit, at least once, by `OutboxDelivery`.
 */
export const outbox = pgTable(
  "outbox",
  {
    /** Claims so far, including the current one. */
    attempts: integer("attempts").notNull().default(0),
    claimToken: uuid("claim_token"),
    claimedUntil: instant("claimed_until"),
    createdAt: instant("created_at").notNull(),
    deliveredAt: instant("delivered_at"),
    /** Identity integer (Drizzle casts `bigint` to text in selects, which breaks `IN (subquery)`). */
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    kind: text("kind").notNull(),
    lastError: text("last_error"),
    nextAttemptAt: instant("next_attempt_at").notNull(),
    payload: jsonb("payload").notNull(),
    status: outboxStatus("status").notNull().default("pending"),
  },
  (t) => [
    index("outbox_due_idx").on(t.status, t.nextAttemptAt),
    check("outbox_kind", oneOf(sql`${t.kind}`, Rec.keys(OutboxMessage.cases))),
    check("outbox_payload_kind", sql`${t.payload} ->> '_tag' = ${t.kind}`),
    check("outbox_attempts", sql`${t.attempts} >= 0`),
    check(
      "outbox_claim",
      sql`(${t.claimToken} is null) = (${t.claimedUntil} is null)`
    ),
    check(
      "outbox_delivered",
      sql`(${t.status} = 'delivered') = (${t.deliveredAt} is not null)`
    ),
  ]
);

/**
 * C12 change audit: one row per write, in the write's transaction. It records the principal (spec 0006, R1): a
 * person id or the name of a scheduled job, never both. There is no foreign key: the audit trail outlives whatever it
 * names.
 */
export const auditLog = pgTable(
  "audit_log",
  {
    action: text("action").notNull(),
    at: instant("at").notNull(),
    client: text("client").notNull().default("server"),
    entity: text("entity").notNull(),
    entityKey: text("entity_key").notNull(),
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    personId: integer("person_id"),
    sessionId: text("session_id"),
    systemJob: text("system_job"),
  },
  (t) => [
    index("audit_log_entity_idx").on(t.entity, t.entityKey),
    index("audit_log_session_idx").on(t.sessionId),
    check("audit_log_client", oneOf(sql`${t.client}`, AuditClient.literals)),
    check("audit_log_action", oneOf(sql`${t.action}`, AuditAction.literals)),
    check("audit_log_entity", oneOf(sql`${t.entity}`, EntityName.literals)),
    check("audit_log_person", sql`${t.personId} is null or ${t.personId} > 0`),
    check(
      "audit_log_system_job",
      oneOf(sql`${t.systemJob}`, SystemJob.literals)
    ),
    check(
      "audit_log_principal",
      sql`(${t.personId} is not null) <> (${t.systemJob} is not null)`
    ),
  ]
);

/**
 * A scheduled job's periods (spec 0008): one row per `(job, period)`, the claim that makes a period run once, the
 * cursor that makes a killed run resume, and the fence (`attempt`) that stops a runner whose lease was taken over.
 * It holds no foreign key and no person: the closure test of spec 0006b has nothing to declare here.
 */
export const jobRun = pgTable(
  "job_run",
  {
    attempt: integer("attempt").notNull().default(0),
    counts: jsonb("counts")
      .notNull()
      .default(sql`'{}'::jsonb`),
    cursor: jsonb("cursor"),
    endedAt: instant("ended_at"),
    job: text("job").notNull(),
    lastError: text("last_error"),
    leaseUntil: instant("lease_until").notNull(),
    outcome: text("outcome").notNull(),
    period: text("period").notNull(),
    startedAt: instant("started_at"),
  },
  (t) => [
    primaryKey({ columns: [t.job, t.period], name: "job_run_pk" }),
    index("job_run_resume_idx").on(t.job, t.outcome),
    check("job_run_job", oneOf(sql`${t.job}`, SystemJob.literals)),
    check(
      "job_run_outcome",
      oneOf(sql`${t.outcome}`, JobRun.RunOutcome.literals)
    ),
    check("job_run_attempt", sql`${t.attempt} >= 0`),
  ]
);

/**
 * The report of one Google Workspace projection run (spec 0008): what the system wants, what the directory held and
 * the difference, written chunk by chunk. People are ids and addresses in the sections, with no foreign key, because
 * a report is a snapshot that outlives what it names (as `audit_log` does).
 */
export const workspaceReport = pgTable(
  "workspace_report",
  {
    accounts: jsonb("accounts")
      .notNull()
      .default(sql`'[]'::jsonb`),
    actual: text("actual").notNull(),
    completedAt: instant("completed_at"),
    counts: jsonb("counts")
      .notNull()
      .default(sql`'{}'::jsonb`),
    departmentLists: jsonb("department_lists")
      .notNull()
      .default(sql`'[]'::jsonb`),
    groups: jsonb("groups")
      .notNull()
      .default(sql`'[]'::jsonb`),
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    issues: jsonb("issues")
      .notNull()
      .default(sql`'[]'::jsonb`),
    mode: text("mode").notNull(),
    period: text("period").notNull(),
    semesterTerm: semesterTerm("semester_term").notNull(),
    semesterYear: integer("semester_year").notNull(),
    startedAt: instant("started_at").notNull(),
    status: text("status").notNull(),
    unmanaged: jsonb("unmanaged")
      .notNull()
      .default(sql`'{"accounts":[],"groups":[]}'::jsonb`),
  },
  (t) => [
    unique("workspace_report_period_unique").on(t.period),
    check(
      "workspace_report_actual",
      oneOf(sql`${t.actual}`, ActualState.literals)
    ),
    check(
      "workspace_report_mode",
      oneOf(sql`${t.mode}`, WorkspaceMode.literals)
    ),
    check(
      "workspace_report_status",
      oneOf(sql`${t.status}`, ReportStatus.literals)
    ),
    check(
      "workspace_report_completed",
      sql`(${t.status} = 'running') = (${t.completedAt} is null)`
    ),
  ]
);
